(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.022-t*0.2)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16+Math.sin(x*0.015+t*0.38)*14;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*20+Math.cos((x-y)*0.012-t*0.1)*15;
  const w2y = Math.cos((y-x)*0.013+t*0.18)*18+Math.sin((x+y)*0.009-t*0.22)*12;
  const sx = x+w1x+w2x*0.5, sy = y+w1y+w2y*0.5;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [330+Math.cos(t*0.45)*100, 155+Math.sin(t*0.6)*60, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 115+Math.cos(t*0.42+1)*95, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 130+Math.cos(t*0.45+4)*80, 0.1, 1.4, 0.8],
    [400+Math.cos(t*0.55+2)*60, 120+Math.sin(t*0.65+1)*70, 0.07, 2.2, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    hS += Math.sin(d*f*1.3-t*sp*0.8+3.1)*w*0.4;
  }
  const act=aS/7.65, inh=iS/7.65, harm=hS/7.65;
  const bg1 = (Math.sin(sx*0.035+sy*0.028+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.06+t*1.3)*Math.cos(sy*0.055-t*1.1)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2=Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.5;
  const spiral=(sp1+sp2)*0.35+sp3;
  const cell1=Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cell2=Math.sin((sx+sy)*0.095+t*0.8)*Math.cos((sx-sy)*0.11-t*0.6);
  const cell=(cell1+cell2)*0.5;
  const rd1 = act - inh*0.65 + bg*0.25 + spiral*0.4;
  const rd2 = act*0.5 - inh*0.9 + harm*0.3 + cell*0.35;
  const reaction = Math.tanh(rd1*2.0)*0.7 + Math.tanh(rd2*1.8)*0.3;
  const detail = Math.sin(sx*0.25+t*0.5)*Math.sin(sy*0.22-t*0.4)*0.15;
  const blend = reaction*0.82 + detail*0.18;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,38,82],[18,72,108],[24,118,128],
    [45,158,132],[120,175,105],[188,172,68],
    [205,138,72],[192,98,82],[165,62,88],
    [120,38,78],[68,22,62],[32,14,55],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction-0.3)*0.15;
  const c0=pal[i], c1=pal[i+1];
  return [
    Math.min(255,((c0[0]+(c1[0]-c0[0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((c0[1]+(c1[1]-c0[1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((c0[2]+(c1[2]-c0[2])*f)*lum*edge+glow*30)|0)
  ];
}
